INSERT OR IGNORE INTO vehicle_engines (generation_id, slug, name, fuel, displacement_cc, power_hp) SELECT g.id, '520d-190', '520d 190', 'diesel', NULL, 190 FROM vehicle_generations g JOIN vehicle_models vm ON vm.id = g.model_id JOIN vehicle_makes mk ON mk.id = vm.make_id WHERE mk.slug = 'bmw' AND vm.slug = '5-series' AND g.slug = '5-series-g30';
INSERT OR IGNORE INTO vehicle_engines (generation_id, slug, name, fuel, displacement_cc, power_hp) SELECT g.id, '530d-265', '530d 265', 'diesel', NULL, 265 FROM vehicle_generations g JOIN vehicle_models vm ON vm.id = g.model_id JOIN vehicle_makes mk ON mk.id = vm.make_id WHERE mk.slug = 'bmw' AND vm.slug = '5-series' AND g.slug = '5-series-g30';

